#include "../../core/runtime/runtime.h"

/* Generated by Phase B of #06.75: carved from runtime.c.
   DO NOT add to this file unless you also update the top-level runtime.c #include order. */

void riven_thread_sleep_ns(int64_t ns) {
    if (ns <= 0) {
        return;
    }

    struct timespec req;
    req.tv_sec = (time_t)(ns / 1000000000LL);
    req.tv_nsec = (long)(ns % 1000000000LL);

    while (nanosleep(&req, &req) == -1 && errno == EINTR) {
    }
}

void riven_thread_yield(void) {
    sched_yield();
}
/* ---------------------------------------------------------------------
 * std::time
 *
 * Two clock sources, both returned as nanoseconds in an int64_t.
 *
 *   - `riven_time_now_ns`  → monotonic clock, suitable for measuring
 *     elapsed time. Never moves backwards. Anchor is unspecified — only
 *     differences are meaningful.
 *
 *   - `riven_time_unix_ns` → realtime clock, nanoseconds since the Unix
 *     epoch (1970-01-01 UTC). Subject to NTP adjustments and manual
 *     clock changes; do not use for measuring elapsed time.
 *
 * Both clamp to 0 on clock_gettime failure (which is effectively never
 * on Linux/macOS but the contract has to say something). Returning 0
 * keeps the type signature simple — no Result wrapping for a syscall
 * that has no failure mode in practice.
 * --------------------------------------------------------------------- */
int64_t riven_time_now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
}

int64_t riven_time_unix_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return 0;
    }
    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
}

/* ---------------------------------------------------------------------
 * std::time::Duration / std::time::Instant + std::thread::sleep
 *
 * Phase 2 stdlib (#06.5 T4) — scalar-wrapper classes around int64_t
 * nanoseconds.
 *
 *   - RivenDuration  = { int64_t nanos }            (8 bytes)
 *   - RivenInstant   = { int64_t monotonic_nanos }  (8 bytes)
 *
 * Both are flat POD heap structs: no inner pointers, no resource
 * ownership. The MIR scope-exit drop pipeline emits the default
 * `riven_dealloc` for any local of type Duration / Instant — neither
 * needs an entry in `user_drop_classes` (no `_drop` helper required).
 *
 * Operator overloads
 *   The language has no general user-side `+`/`-` overload mechanism;
 *   built-in types get hard-coded special-cases in
 *   `mir/lower/expr/binops.rs` (String concat, Vec/Map/Set equality,
 *   etc.). We follow that pattern — `Duration + Duration`,
 *   `Duration - Duration`, and `Instant - Instant` route to the
 *   `riven_duration_add` / `riven_duration_sub` / `riven_instant_sub`
 *   helpers below. The named `.add()` / `.sub()` methods are wired in
 *   parallel as the path that survives generic code where the binop
 *   isn't statically resolved.
 *
 * Saturation
 *   `riven_duration_sub(a, b)` saturates to zero when `a < b` — the
 *   public contract is "Duration is non-negative". Add overflow
 *   triggers `riven_panic("Duration arithmetic overflow")`; matches the
 *   "panic on representation overflow" stance from
 *   `riven_int_to_string` and friends.
 *
 * Instant ordering
 *   `riven_instant_duration_since(self, earlier)` panics if
 *   `earlier > self`. This is the documented Rust-style contract — a
 *   monotonic clock that goes backwards is a programmer error, not an
 *   I/O failure, so no Result wrapping.
 * --------------------------------------------------------------------- */

#define RIVEN_NS_PER_SEC   1000000000LL
#define RIVEN_NS_PER_MILLI 1000000LL
#define RIVEN_NS_PER_MICRO 1000LL

/* RivenDuration struct body lives in runtime.h so net/tcp.c can read
 * `->nanos` when wiring SO_RCVTIMEO / SO_SNDTIMEO. RivenInstant is
 * declared opaque in runtime.h; we promote it here to a full
 * definition for the time.c-internal helpers below. Pinned size
 * checks remain. */
typedef struct RivenInstant {
    int64_t monotonic_nanos;
} RivenInstant;

_Static_assert(sizeof(RivenDuration) == 8,
    "RivenDuration wire layout drifted from documented 8-byte form");

_Static_assert(sizeof(RivenInstant) == 8,
    "RivenInstant wire layout drifted from documented 8-byte form");

static RivenDuration *riven_duration_alloc(int64_t nanos) {
    RivenDuration *d = (RivenDuration *)riven_alloc(sizeof(RivenDuration));
    d->nanos = nanos;
    return d;
}

static RivenInstant *riven_instant_alloc(int64_t monotonic_nanos) {
    RivenInstant *i = (RivenInstant *)riven_alloc(sizeof(RivenInstant));
    i->monotonic_nanos = monotonic_nanos;
    return i;
}

/* `from_secs(s)` — multiply guarded against signed int64 overflow.
 * The boundary is `INT64_MAX / NS_PER_SEC` (~292 years) on the
 * positive side and `INT64_MIN / NS_PER_SEC` on the negative.
 * Beyond that, panic — the alternative is silent UB on signed
 * overflow which is unacceptable for a stdlib clock primitive. */
RivenDuration *riven_duration_from_secs(int64_t s) {
    if (s > INT64_MAX / RIVEN_NS_PER_SEC || s < INT64_MIN / RIVEN_NS_PER_SEC) {
        riven_panic("Duration.from_secs overflow");
    }
    return riven_duration_alloc(s * RIVEN_NS_PER_SEC);
}

RivenDuration *riven_duration_from_millis(int64_t ms) {
    if (ms > INT64_MAX / RIVEN_NS_PER_MILLI || ms < INT64_MIN / RIVEN_NS_PER_MILLI) {
        riven_panic("Duration.from_millis overflow");
    }
    return riven_duration_alloc(ms * RIVEN_NS_PER_MILLI);
}

RivenDuration *riven_duration_from_micros(int64_t us) {
    if (us > INT64_MAX / RIVEN_NS_PER_MICRO || us < INT64_MIN / RIVEN_NS_PER_MICRO) {
        riven_panic("Duration.from_micros overflow");
    }
    return riven_duration_alloc(us * RIVEN_NS_PER_MICRO);
}

RivenDuration *riven_duration_from_nanos(int64_t ns) {
    return riven_duration_alloc(ns);
}

int64_t riven_duration_as_secs(RivenDuration *d) {
    if (!d) {
        riven_panic("Duration.as_secs on null receiver");
    }
    return d->nanos / RIVEN_NS_PER_SEC;
}

int64_t riven_duration_as_millis(RivenDuration *d) {
    if (!d) {
        riven_panic("Duration.as_millis on null receiver");
    }
    return d->nanos / RIVEN_NS_PER_MILLI;
}

int64_t riven_duration_as_micros(RivenDuration *d) {
    if (!d) {
        riven_panic("Duration.as_micros on null receiver");
    }
    return d->nanos / RIVEN_NS_PER_MICRO;
}

int64_t riven_duration_as_nanos(RivenDuration *d) {
    if (!d) {
        riven_panic("Duration.as_nanos on null receiver");
    }
    return d->nanos;
}

/* Checked sum: panic on int64 overflow. Mirrors Rust's
 * `Duration::checked_add` returning None — we don't ship Option-of-
 * Duration yet, so the contract is "panic" instead. */
RivenDuration *riven_duration_add(RivenDuration *a, RivenDuration *b) {
    if (!a || !b) {
        riven_panic("Duration.+ on null receiver");
    }
    int64_t x = a->nanos;
    int64_t y = b->nanos;
    if (((y > 0) && (x > INT64_MAX - y)) || ((y < 0) && (x < INT64_MIN - y))) {
        riven_panic("Duration addition overflow");
    }
    return riven_duration_alloc(x + y);
}

/* Saturating subtract: result clamps to zero on `a < b`. This is the
 * Duration-is-non-negative contract; underflow on a clock primitive
 * almost always means "the elapsed time hasn't passed yet" and a
 * zero is the unambiguous neutral value. */
RivenDuration *riven_duration_sub(RivenDuration *a, RivenDuration *b) {
    if (!a || !b) {
        riven_panic("Duration.- on null receiver");
    }
    int64_t x = a->nanos;
    int64_t y = b->nanos;
    if (x <= y) {
        return riven_duration_alloc(0);
    }
    return riven_duration_alloc(x - y);
}

/* CLOCK_MONOTONIC sample. Returns 0 on clock_gettime failure (the
 * same contract as `riven_time_now_ns` — there's no documented
 * failure path on Linux/macOS in practice). */
RivenInstant *riven_instant_now(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return riven_instant_alloc(0);
    }
    return riven_instant_alloc((int64_t)ts.tv_sec * RIVEN_NS_PER_SEC + (int64_t)ts.tv_nsec);
}

RivenDuration *riven_instant_elapsed(RivenInstant *t) {
    if (!t) {
        riven_panic("Instant.elapsed on null receiver");
    }
    struct timespec ts;
    int64_t now_ns;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        now_ns = t->monotonic_nanos;
    } else {
        now_ns = (int64_t)ts.tv_sec * RIVEN_NS_PER_SEC + (int64_t)ts.tv_nsec;
    }
    if (now_ns < t->monotonic_nanos) {
        /* Monotonic clock contract guarantees this can't happen, but if
         * the kernel ever lies, surface zero rather than a negative. */
        return riven_duration_alloc(0);
    }
    return riven_duration_alloc(now_ns - t->monotonic_nanos);
}

/* `self.duration_since(earlier)` — panics if `earlier > self`.
 * Same semantics drives `Instant - Instant`. */
RivenDuration *riven_instant_duration_since(RivenInstant *self, RivenInstant *earlier) {
    if (!self || !earlier) {
        riven_panic("Instant.duration_since on null receiver");
    }
    if (earlier->monotonic_nanos > self->monotonic_nanos) {
        riven_panic("Instant.duration_since: earlier is in the future");
    }
    return riven_duration_alloc(self->monotonic_nanos - earlier->monotonic_nanos);
}

RivenDuration *riven_instant_sub(RivenInstant *a, RivenInstant *b) {
    /* Same semantics as duration_since(a, b). */
    return riven_instant_duration_since(a, b);
}

/* Thin wrapper that unpacks a `Duration *` and delegates to the
 * existing `riven_thread_sleep_ns(int64)`. The latter's signature
 * stays untouched — the v1 `Thread.sleep(int)` static method still
 * calls it directly. */
void riven_thread_sleep_duration(RivenDuration *d) {
    if (!d) {
        return;
    }
    riven_thread_sleep_ns(d->nanos);
}
